import json,pathlib,hashlib
R=pathlib.Path(__file__).resolve().parent
load=lambda f:json.loads((R/f).read_text())
def save(f,x):(R/f).write_text(json.dumps(x,indent=2)+'\n')
old=load('../review-1-policy-2-33f27ec8b7c41b11/pedagogical-variation.json')
p={k:old[k] for k in ['learner_operation','fixed_features','answer_roles','counterfactuals']}
p['answer_roles'][0]['observed']='Sign, value, numerical rank and position vary. Exact delivered q-73544 pair has ranks 4 and 5. Every sampled family has contrasting ranks.'
for c in p['counterfactuals']:
 c['change']=c['change'].replace('737837','920223')
 c['sample_refs']=['focused-counterfactual-records.json','focused-counterfactual-results.json','native-results.json','render-focused/rendering.json','visual-inspection.json']
p['coverage']=[
 {'case':'All ten source profiles and complete answer banks','sample_refs':['source-replays.json','source-replay-results.json'],'result':'All ten prompts, solutions, complete banks and keys match after presentation normalization.'},
 {'case':'Fresh seed 820219; six boundary/interior parameters per source profile; 15-record easy control seed 920221','sample_refs':['samples.json','control.json','math-results.json','shortcut-results.json'],'result':'80 total sampled/control/batch records verified independently. Integer/fractional profiles and both endpoints retained; positive, zero and negative values covered.'},
 {'case':'Both retained failure predicates checked before and after their repairs','sample_refs':['repair-verification.json','verify-regressions.py','regression-fixtures/before1/evidence/regressions/retained-records.json','regression-fixtures/before2/evidence/repair-2/exact-records.json','regression-fixtures/current/evidence/repair-2/exact-records.json'],'result':'Original rank-2 defect and subsequent rank-4 finite-batch defect cause the respective checks to exit 1. Current versions exit 0. Read preflight and both retained history findings; independently reconfirmed their claims.'},
 {'case':'Exact runner batch seed 3334594587 and effective resampled seeds','sample_refs':['batch.json','delivery-batch/accepted.json','changed-path-results.json','batch-resampling-records.json'],'result':'Seven generator calls produce five questions, all surviving delivery. Repeated q-73544 ranks are 4 and 5; original rank-4 strategy now scores 1/2. Effective seeds exactly reproduce all five records.'}]
p['shortcut_probes']=[]
for file,rows in load('decision-probe-results.json').items():
 if file not in ['samples.json','delivery-batch/accepted.json','delivery-control/accepted.json']:continue
 for r in rows:
  if r['total']<2:continue
  p['shortcut_probes'].append({'cue':r['strategy'],'subgroup':file+': '+r['subgroup'],'scope':'overall' if r['subgroup']=='all' else 'within_template','strategy':'Choose the unique option satisfying '+r['strategy']+'; abstain if ambiguous or unavailable.','correct':r['correct'],'total':r['total'],'baseline':0.2,'disposition':'not_predictive','conclusion':f"{r['correct']}/{r['total']} full questions answered correctly; unique-choice strategy applied to {r['attempted']}. Abstentions count as unsuccessful. Random choice among five is 0.2. No perfect repeatable subgroup predictor demonstrated; finite counts do not establish population rates. Authored positions are additionally shuffled by the UI.",'sample_refs':[file,'decision-probe-results.json','decision-probes.py']})
p['delivery']={'stages_examined':['Finite candidate enumeration and source-offset exclusion','Solution-fingerprint rejection and bank-seed resampling','Requested difficulty and publisher normalization/validation','Captured inventory and within-batch deduplication','Learner retirement/freshness and within-band hash selection; unconfigured fallback','Actual UI option ordering'], 'sample_refs':['batch-resampling-records.json','changed-path-results.json','sampler-attempts.json','delivery-analysis.json','delivery-batch/delivery.json','delivery-batch/accepted.json','delivery-control/delivery.json','delivery-control/accepted.json','decision-probe-results.json','render/rendering.json'], 'result':'Exact batch: 7 generation calls -> 5 outputs -> 5 accepted. Fresh control: 15 calls -> 15 outputs -> 15 accepted. Batch ranks [4,5,5,1,5], with q-73544 ranks [4,5]; all five easy families and negative/zero/positive solutions survive in control. Same-band selection uses record IDs/history, not answer rank; fixture samples fresh prefixes. Live learner histories and weights are not captured and can select smaller subsets.'}
p['limitations']=['Finite probes support the tested claims; they cannot exclude every possible shortcut.','Coefficient profiles and offset bounds are conservative finite practice, not exhaustive coverage of all nonsingular systems. Hard has no supported source bank.','Captured inventory basis 5576 contains exactly ten original source questions and no generated stored records. affected-inventory.json is verified empty for the demonstrated defects, not an untested pool.','Publication preparation absent; actual check_delivery reproduced filtering read-only. Concurrent inventory, future entity IDs, active band weights and learner history are unknown; all relevant rules were examined and selection fixtures are explicitly conditional.','Source-replay banks retain original examples; direct replay remains available but batch excludes [0,0]. Both supported response endpoints were checked; there is no target-switch parameter.']
save('pedagogical-variation.json',p)
save('visual-inspection.json',{'passed':True,'screenshots_inspected':['render/question-001.png','render/question-003.png','render/question-005.png','render/question-006.png','render-focused/question-001.png','render-focused/question-002.png','render-focused/question-003.png','render-focused/question-004.png'],'observations':'Actual UI shows readable equations, augmented separators, fractions, radio choices, complete elimination steps and back substitution without clipping. Controlled second RHS 14 -> 15 changes solution (0,-2) -> (2,-1); old response is visibly incorrect after change. Reversing choices preserves math and correct response. Both exact-batch q-73544 banks and REF-only profile visually checked. Renderer defaults to six cases; separate four-case focused rendering covers both pair members, reversed order and moderate fractional profile.'})
checks={}
def check(k,paths,details):checks[k]={'status':'passed','evidence_paths':paths,'details':details}
check('source_replay',['source-replay-results.json','source-replays.json'],'All ten supported source prompts, complete five-choice banks, keys and solutions replay after presentation normalization.')
check('math',['audit.py','math-results.json','focused-counterfactual-results.json'],'Exact arithmetic independently verifies 80 sampled/control/batch records, unique correct choices and all displayed solution matrices.')
check('variety',['shortcut-results.json','decision-probe-results.json','changed-path-results.json','delivery-analysis.json'],'All ten profiles retained. Repeated delivered family now contrasts ranks 4 and 5; sampled constants and answer roles vary after filtering.')
check('scope',['source-analysis.json','revision.diff','math-results.json'],'Changed batch rules only resample bank seeds and exclude exact source replays; supported arithmetic, elimination stages and response endpoints remain intact.')
check('grading',['all-native-input.json','native-results.json'],'Native grader returns 92 expected acceptances and 368 expected rejections, including controlled pairs and normalized delivered records. All fields are radio; free-entry notation is inapplicable.')
check('rendering',['render/rendering.json','render-focused/rendering.json','visual-inspection.json'],'Actual UI rendered all five batch questions and controlled cases. Representative screenshots inspected for notation, controls and full worked solutions.')
check('packaging',['packaging-results.json','changed-path-results.json','repair-verification.json','package-integrity.json'],'Exact Python/SymPy dependencies, deterministic replay, effective resampling seeds, relocation and invalid-input rejection pass. Both retained checks fail their original examples and pass current code. Package unchanged.')
check('decision_variation',['pedagogical-variation.json','decision-probe-results.json','batch-shortcut-results.json','delivery-analysis.json'],'Relevant and irrelevant controlled changes agree across prompt, explanation, grader and UI. Conditional shortcut probes do not reproduce prior defects in current delivered batch.')
s=load('source-analysis.json');s={k:s[k] for k in ['skill','reasoning_steps','invariants','permitted_variations','source_refs','evidence_paths']}
result={'verdict':'accepted','summary':'Both retained shortcut defects are repaired. All eight independent checks pass for the current package and five-question batch; no affected generated inventory records were found.','source_analysis':s,'checks':checks,'findings':[]}
save('result.json',result)
# Bind integrity to every package file, not merely manifest runtime files.
before=load('package-all-hashes-before.json');w=R.parent/'workspace';after={str(f.relative_to(w)):hashlib.sha256(f.read_bytes()).hexdigest() for f in w.rglob('*') if f.is_file()}
save('package-integrity.json',{'unchanged':before==after,'before_count':len(before),'after_count':len(after),'differences':[k for k in before.keys()|after.keys() if before.get(k)!=after.get(k)]});assert before==after
for c in checks.values():
 for f in c['evidence_paths']:assert (R/f).is_file() and (R/f).stat().st_size>0,f
for collection in ['coverage','counterfactuals','shortcut_probes']:
 for row in p[collection]:
  for f in row['sample_refs']:assert (R/f).is_file() and (R/f).stat().st_size>0,f
for f in p['delivery']['sample_refs']:assert (R/f).is_file() and (R/f).stat().st_size>0,f
assert load('render/rendering.json')['passed'] and load('render-focused/rendering.json')['passed']
assert all(all(row[k] for k in ['prompt','solution','complete_bank','key']) for row in load('source-replay-results.json'))
assert all(row['solution_stages_valid'] and row['uniquely_correct'] for row in load('math-results.json'))
save('evidence-validation.json',{'all_evidence_paths_nonempty':True,'package_unchanged':True,'all_eight_checks_passed':True})
(R/'session-state.md').write_text('Complete: accepted. Both retained regression predicates fail original generators and pass current package. 80 independent exact-math cases; 460 expected native outcomes; actual UI batch and controlled cases inspected. Five batch and 15 control records survive delivery; q-73544 ranks contrast 4/5. Inventory basis 5576 has only ten original source questions. Package hashes unchanged. Final result.json and pedagogical-variation.json written; evidence references verified.\n')
print(json.dumps({'verdict':result['verdict'],'package_unchanged':before==after,'shortcut_probes':len(p['shortcut_probes'])}))
